// Browser page returned by your current STM32 firmware is HTML, not JSON.
// Extract ONLY values from the three labeled <p> fields.
if (msg.statusCode !== 200) { node.warn('STM32 HTTP status: '+msg.statusCode); return null; }
const html = String(msg.payload || '');
// Simpler robust patterns allowing markup after labels.
const t = html.match(/Temperature:\s*(-?\d+(?:\.\d+)?)/i);
const p = html.match(/Pressure:\s*(-?\d+(?:\.\d+)?)/i);
const h = html.match(/Humidity:\s*(-?\d+(?:\.\d+)?)/i);
if (!t || !p || !h) { node.warn('Could not parse sensor HTML. Check if sensor is unavailable and print msg.payload to debug.'); return null; }
const obj={temp:Number(t[1]), pressure:Number(p[1]), humidity:Number(h[1]), at:Date.now(), source:'BME280'};
if (!Number.isFinite(obj.temp)||!Number.isFinite(obj.pressure)||!Number.isFinite(obj.humidity)) return null;
msg.payload=obj; msg.topic='local'; return msg;

const key = "a76dcc4675c13fe0b91fe39fafa7419e";

msg.url = "https://api.openweathermap.org/data/2.5/weather"
        + "?q=Chennai,IN"
        + "&units=metric"
        + "&appid=" + encodeURIComponent(key);

return msg;

if (msg.statusCode!==200 || !msg.payload || !msg.payload.main) {
 node.warn('OpenWeather error HTTP '+msg.statusCode+': '+JSON.stringify(msg.payload)); return null;
}
const m=msg.payload.main;
msg.payload={temp:Number(m.temp),humidity:Number(m.humidity),pressure:Number(m.pressure),at:Date.now(),source:'OpenWeather',location:msg.payload.name||'Configured city'};
msg.topic='api';return msg;

const p = msg.payload || {};
const now = Date.now();

// Store the latest reading from each source.
if (msg.topic === "local") {
  flow.set("agro_local", {
    ...p,
    receivedAt: now
  });
}

if (msg.topic === "api") {
  flow.set("agro_api", {
    ...p,
    receivedAt: now
  });
}

const local = flow.get("agro_local");
const api = flow.get("agro_api");

// Validate sensor values.
const valid = d => {
  if (!d) return false;

  const t = Number(d.temp);
  const h = Number(d.humidity);
  const pr = Number(d.pressure);

  return Number.isFinite(t) &&
    Number.isFinite(h) &&
    Number.isFinite(pr) &&
    t >= -20 && t <= 60 &&
    h >= 0 && h <= 100 &&
    pr >= 850 && pr <= 1100;
};

// Check freshness using Node-RED reception time.
const fresh = (d, limit) =>
  d &&
  Number.isFinite(Number(d.receivedAt)) &&
  now - Number(d.receivedAt) >= 0 &&
  now - Number(d.receivedAt) < limit;

const localOK = valid(local) && fresh(local, 2 * 60 * 1000);
const apiOK = valid(api) && fresh(api, 25 * 60 * 1000);

const output = {
  ready: localOK || apiOK,
  local: localOK ? local : null,
  api: apiOK ? api : null,
  index: null,
  category: "Waiting for valid data",
  source: "No valid source",
  agreement: null,
  delta: null,
  indicators: [],
  advisories: [],
  warnings: [],
  note: "Universal rule-based environmental assessment using ambient temperature, humidity and atmospheric pressure. Not a crop yield or irrigation prediction."
};

if (!localOK)
  output.warnings.push(
    "Local BME280 data unavailable, invalid or outdated."
  );

if (!apiOK)
  output.warnings.push(
    "OpenWeather data unavailable, invalid or outdated."
  );

if (!output.ready) {
  msg.payload = output;
  return msg;
}

// Use both sources when available.
// Give greater importance to hyperlocal sensor readings.
const bothAvailable = localOK && apiOK;

const weightLocal = bothAvailable ? 0.65 : localOK ? 1 : 0;
const weightAPI = bothAvailable ? 0.35 : apiOK ? 1 : 0;

const chosen = localOK ? local : api;

const t = weightLocal * Number(localOK ? local.temp : 0) +
  weightAPI * Number(apiOK ? api.temp : 0);

const h = weightLocal * Number(localOK ? local.humidity : 0) +
  weightAPI * Number(apiOK ? api.humidity : 0);

const pressure = weightLocal * Number(localOK ? local.pressure : 0) +
  weightAPI * Number(apiOK ? api.pressure : 0);

const clamp = (n, min = 0, max = 100) =>
  Math.max(min, Math.min(max, n));

// Universal environmental suitability heuristic.
const tempScore = clamp(
  100 -
  Math.max(0, t - 30) * 5 -
  Math.max(0, 15 - t) * 3
);

const humidityScore = clamp(
  100 -
  Math.max(0, h - 80) * 2 -
  Math.max(0, 30 - h) * 1.5
);

// Atmospheric pressure is informational in this model.
// It is not treated as a direct crop-health measurement.
const environmentalScore =
  0.60 * tempScore +
  0.40 * humidityScore;

// Compare the two sources when both are available.
if (bothAvailable) {
  const dt = Math.abs(Number(local.temp) - Number(api.temp));
  const dh = Math.abs(Number(local.humidity) - Number(api.humidity));
  const dp = Math.abs(Number(local.pressure) - Number(api.pressure));

  output.delta = {
    temp: Number(dt.toFixed(2)),
    humidity: Number(dh.toFixed(2)),
    pressure: Number(dp.toFixed(2))
  };

  output.agreement = Math.round(clamp(
    100 - Math.min(60, dt * 10) -
    Math.min(40, dh * 1.2)
  ));

  if (dt > 4 || dh > 15)
    output.warnings.push(
      "Local microclimate differs noticeably from city-level weather data. Check sensor placement and surrounding conditions."
    );

  if (dp > 8)
    output.warnings.push(
      "Pressure readings differ noticeably. Verify sensor calibration and measurement conditions."
    );
}

// Apply a modest consistency adjustment when both sources work.
const reliabilityFactor = bothAvailable
  ? 0.85 + 0.15 * output.agreement / 100
  : 1;

output.index = Math.round(
  clamp(environmentalScore * reliabilityFactor)
);

output.category =
  output.index >= 95 ? "Favorable" :
    output.index >= 93 ? "Generally Suitable" :
      output.index >= 91 ? "Use Caution" :
        "Unfavorable";

output.source = bothAvailable
  ? "BME280 + OpenWeather"
  : localOK ? "Local BME280" : "OpenWeather";

// Environmental indicators.
output.indicators.push({
  title: "🌡️ Temperature",
  level: t > 35 ? "High" :
    t > 30 ? "Elevated" :
      t < 15 ? "Low" : "Moderate",
  detail: `Combined temperature reading: ${t.toFixed(2)} °C.`
});

output.indicators.push({
  title: "💧 Atmospheric Humidity",
  level: h > 85 ? "Very High" :
    h > 80 ? "High" :
      h < 30 ? "Low" : "Moderate",
  detail: `Combined relative humidity: ${h.toFixed(2)}%.`
});

output.indicators.push({
  title: "🧭 Atmospheric Pressure",
  level: pressure < 1000 ? "Low" :
    pressure > 1025 ? "High" : "Normal",
  detail: `Combined atmospheric pressure: ${pressure.toFixed(2)} hPa.`
});

output.indicators.push({
  title: "📡 Data Consistency",
  level: !bothAvailable ? "Single Source" :
    output.agreement >= 80 ? "Strong" :
      output.agreement >= 50 ? "Moderate" : "Low",
  detail: bothAvailable
    ? `Source agreement: ${output.agreement}/100.`
    : "Only one valid data source is currently available."
});

// Smart field advisories.
if (t > 29)
  output.advisories.push(
    "High ambient temperature detected. Monitor field heat conditions and potential plant water stress."
  );
else if (t > 27)
  output.advisories.push(
    "Warm environmental conditions detected. Monitor field temperature changes."
  );
else if (t < 25)
  output.advisories.push(
    "Low ambient temperature detected. Monitor temperature-sensitive field conditions."
  );

if (h > 85)
  output.advisories.push(
    "Very high humidity detected. Monitor leaf wetness and conditions favorable to fungal diseases."
  );
else if (h > 80)
  output.advisories.push(
    "High humidity detected. Monitor prolonged moisture exposure in the field."
  );
else if (h < 30)
  output.advisories.push(
    "Low atmospheric humidity detected. Monitor soil moisture separately; air humidity alone cannot determine irrigation requirements."
  );

if (bothAvailable && output.agreement < 70)
  output.advisories.push(
    "Check local sensor placement and compare readings with nearby environmental conditions."
  );

if (output.advisories.length === 0)
  output.advisories.push(
    "No major temperature or humidity warning detected under the current assessment rules. Continue routine field monitoring."
  );

output.advisories.push(
  "Check rainfall forecasts, wind conditions and soil moisture before irrigation, spraying or other weather-sensitive operations."
);

msg.payload = output;
return msg;
